<?php
declare(strict_types=1);namespace QualitySystem\Controllers;require_once dirname(__DIR__,2).'/security.php';use PDO;use QualitySystem\Repositories\CourseReportRepository;use QualitySystem\Security\PermissionMatrix;use QualitySystem\Services\CourseReportService;use QualitySystem\Services\CourseReportValidationException;
final class CourseReportController{private CourseReportRepository$repo;private CourseReportService$service;public function __construct(PDO$pdo,private readonly string$root){$this->repo=new CourseReportRepository($pdo);$this->service=new CourseReportService($pdo,$this->repo);}public function dispatch(string$path,string$method):void{$role=(string)($_SESSION['role']??'');$user=(int)($_SESSION['user_id']??0);if(!PermissionMatrix::allows($role,'course_reports','view'))$this->abort(403,'Access denied.');if($path==='/course-reports'&&$method==='GET'){$this->index($role,$user);return;}if($path==='/course-reports/create'){if(!PermissionMatrix::allows($role,'course_reports','create'))$this->abort(403,'Access denied.');$method==='POST'?$this->save(null,$role,$user):$this->form(null,$role,$user);return;}if(preg_match('#^/course-reports/(\d+)/edit$#',$path,$m)){if(!PermissionMatrix::allows($role,'course_reports','update'))$this->abort(403,'Access denied.');$method==='POST'?$this->save((int)$m[1],$role,$user):$this->form((int)$m[1],$role,$user);return;}if(preg_match('#^/course-reports/(\d+)/delete$#',$path,$m)&&$method==='POST'){try{$this->service->delete((int)$m[1],$role,$user);header('Location: /course-reports');}catch(\RuntimeException$e){$this->abort(in_array($e->getCode(),[403,404],true)?$e->getCode():500,$e->getMessage());}return;}$this->abort(404,'Not found.');}private function index(string$r,int$u):void{$page=max(1,(int)($_GET['page']??1));$perPage=min(50,max(10,(int)($_GET['per_page']??20)));$f=[];foreach(['search','academic_year','semester','status']as$x)$f[$x]=mb_substr(trim((string)($_GET[$x]??'')),0,100);$data=$this->repo->paginate($r,$u,$page,$perPage,$f);$this->render('course_reports/index',$data+compact('page','perPage','f','r'));}private function form(?int$id,string$r,int$u,array$errors=[],array$i=[]):void{$report=$id!==null?$this->repo->findScoped($id,$r,$u):['academic_year'=>date('Y').'-'.(date('Y')+1),'report_date'=>date('Y-m-d'),'report_version'=>'v1.0','status'=>'Draft'];if($id!==null&&!$report)$this->abort(404,'Course report not found.');if($i)$report=array_merge($report,$i);$this->render('course_reports/form',['report'=>$report,'errors'=>$errors,'specifications'=>$this->repo->courseSpecifications($r,$u)]);}private function save(?int$id,string$r,int$u):void{try{$this->service->save($_POST,$r,$u,$id);header('Location: /course-reports');}catch(CourseReportValidationException$e){http_response_code(422);$this->form($id,$r,$u,$e->errors,$_POST);}catch(\RuntimeException$e){$this->abort(in_array($e->getCode(),[403,404],true)?$e->getCode():500,$e->getMessage());}}private function render(string$t,array$d):void{extract($d,EXTR_SKIP);require$this->root.'/templates/'.$t.'.php';}private function abort(int$s,string$m):never{http_response_code($s);exit(htmlspecialchars($m,ENT_QUOTES));}}
